input.command:
cd /home/user/rating-app
cat << 'EOF' > svelte.config.js
import adapter from '@sveltejs/adapter-node';

/** @type {import('@sveltejs/kit').Config} */
const config = {
	kit: {
		adapter: adapter()
	}
};

export default config;
EOF

cat << 'EOF' > vite.config.js
import { sveltekit } from '@sveltejs/kit/vite';
import { defineConfig } from 'vite';

export default defineConfig({
	plugins: [sveltekit()]
});
EOF

mkdir -p src/lib src/routes

cat << 'EOF' > src/app.html
<!doctype html>
<html lang="en">
	<head>
		<meta charset="utf-8" />
		<meta name="viewport" content="width=device-width, initial-scale=1" />
		%sveltekit.head%
	</head>
	<body data-sveltekit-preload-data="hover">
		<div style="display: contents">%sveltekit.body%</div>
	</body>
</html>
EOF

cat << 'EOF' > src/lib/StarRating.svelte
<script>
	let { value = $bindable(0), max = 5 } = $props();
</script>

<div class="star-rating">
	{#each Array(max) as _, i}
		<button
			class="star"
			class:filled={i < value}
			data-filled={i < value ? 'true' : 'false'}
			onclick={() => (value = i + 1)}
		>
			★
		</button>
	{/each}
</div>

<style>
	.star {
		background: none;
		border: none;
		font-size: 2rem;
		cursor: pointer;
		color: #ccc;
	}
	.star.filled {
		color: gold;
	}
</style>
EOF

cat << 'EOF' > src/routes/+page.svelte
<script>
	import StarRating from '$lib/StarRating.svelte';

	let rating = $state(0);

	function resetRating() {
		rating = 0;
	}
</script>

<h1>Rating: {rating}</h1>

<StarRating bind:value={rating} />

<button onclick={resetRating}>Reset</button>
EOF

